# Try hypothesis: Fill cells that have 2 on BOTH left AND right in their row OR on BOTH above AND below in their column
def predict_hypothesis(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # copy

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue

            # Check horizontal: 2 on both left and right
            has_left_2 = False
            has_right_2 = False
            for dc in range(1, min(c+1, w)):
                if grid[r][c-dc] == 2:
                    has_left_2 = True
            for dc in range(1, min(w-c, w)):
                if grid[r][c+dc] == 2:
                    has_right_2 = True
            if has_left_2 and has_right_2:
                result[r][c] = 1

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if result[r][c] != 0:
                continue

            # Check vertical: 2 on both above and below  
            has_above_2 = False
            has_below_2 = False
            for dr in range(1, min(r+1, h)):
                if grid[r-dr][c] == 2:
                    has_above_2 = True
            for dr in range(1, min(h-r, h)):
                if grid[r+dr][c] == 2:
                    has_below_2 = True
            if has_above_2 and has_below_2:
                result[r][c] = 1

    return result

predicted = predict_hypothesis(demo_input)

