# Try different hypothesis
def predict_v2(grid):
    """Fill cells that have 2s on both sides in a minimal way"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Horizontal: for each row, find pairs of 2s with exactly one 0 between them and fill that 0
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == 2]
        for i in range(len(positions)):
            for j in range(i+1, len(positions)):
                left_pos = positions[i]
                right_pos = positions[j]
                # Fill all zeros between them, except skip positions that already have something
                for c in range(left_pos+1, right_pos):
                    if result[r][c] == 0:
                        result[r][c] = 1

    # Vertical: same thing for columns
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == 2]
        for i in range(len(positions)):
            for j in range(i+1, len(positions)):
                top_pos = positions[i]
                bottom_pos = positions[j]
                for r in range(top_pos+1, bottom_pos):
                    if result[r][c] == 0:
                        result[r][c] = 1

    return result

predicted = predict_v2(demo_input)

# Check differences
diffs = []
for r in range(10):
    for c in range(15):
        if predicted[r][c] != demo_output[r][c]:
            diffs.append(((r,c), predicted[r][c], demo_output[r][c]))

if diffs:
