# Proposed rule: fill cell (r,c) if there's a 2 in the same row AND a 2 in the same column
# such that (r,c) lies between them (not including the 2s themselves)
def predict_v3(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue

            # Has 2 to the left?
            has_left_2 = any(grid[r][cc] == 2 for cc in range(c))
            # Has 2 to the right?
            has_right_2 = any(grid[r][cc] == 2 for cc in range(c+1, w))
            # Has 2 above?
            has_above_2 = any(grid[rr][c] == 2 for rr in range(r))
            # Has 2 below?
            has_below_2 = any(grid[rr][c] == 2 for rr in range(r+1, h))

            # Fill if has 2s on opposite sides horizontally OR vertically
            if (has_left_2 and has_right_2) or (has_above_2 and has_below_2):
                result[r][c] = 1

    return result

predicted = predict_v3(demo_input)
