# New hypothesis: For each row/col, process pairs of 2s
# Fill between consecutive pair IF:
# - Horizontal: gap > 1 AND there's another 2 further away
# - Vertical: gap == 1 (only single cells get filled)

def predict_v4(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Process rows
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == 2]
        for i in range(len(positions)):
            if i+1 < len(positions):
                left_pos = positions[i]
                right_pos = positions[i+1]
                gap = right_pos - left_pos - 1

                # Horizontal: fill if gap > 1
                if gap > 1:
                    for c in range(left_pos+1, right_pos):
                        result[r][c] = 1

    # Process columns
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == 2]
        for i in range(len(positions)):
            if i+1 < len(positions):
                top_pos = positions[i]
                bottom_pos = positions[i+1]
                gap = bottom_pos - top_pos - 1

                # Vertical: fill if gap == 1
                if gap == 1:
                    result[top_pos+1][c] = 1

    return result

predicted = predict_v4(demo_input)
diffs = []
for r in range(10):
