# Find all rectangles
def find_rectangles(grid):
    h, w = len(grid), len(grid[0])
    rects = []

    # For each pair of rows
    for r1 in range(h):
        for r2 in range(r1+1, h):
            # Find columns that have 2s in BOTH rows
            common_cols = [c for c in range(w) if grid[r1][c] == 2 and grid[r2][c] == 2]
            if len(common_cols) >= 2:
                # For each pair of common columns, check if it's a valid rectangle
                for c1 in range(len(common_cols)):
                    for c2 in range(c1+1, len(common_cols)):
                        # This defines a rectangle from (r1, c1) to (r2, c2)
                        # Check if all four corners have 2s (they do by definition)
                        rects.append(((r1, c1), (r2, c2)))

    return rects

rects = find_rectangles(demo_input)
print(f"\nFound {len(rects)} rectangles:")
for rect in rects:
    print(f"  {rect}")

# Fill interiors of rectangles
def predict_rectangle_fill(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Get all unique row pairs with matching columns
    for r1 in range(h):
        for r2 in range(r1+1, h):
            common_cols = [c for c in range(w) if grid[r1][c] == 2 and grid[r2][c] == 2]
            if len(common_cols) < 2:
                continue

            # Sort common columns
            common_cols.sort()

            # Fill between consecutive column pairs
            for i in range(len(common_cols)-1):
                c1 = common_cols[i]
                c2 = common_cols[i+1]

                # Fill interior rows (between r1 and r2) and interior cols (between c1 and c2)
                for rr in range(r1+1, r2):
                    for cc in range(c1+1, c2):
                        if grid[rr][cc] == 0:
                            result[rr][cc] = 1

    return result

pred = predict_rectangle_fill(demo_input)

diffs = []
for r in range(10):
    for c in range(15):
        if pred[r][c] != demo_output[r][c]:
            diffs.append(((r,c), pred[r][c], demo_output[r][c]))

if diffs:
    print("\nDifferences:")
    for pos, p, a in diffs:
        print(f"  ({pos}) got {p}, expected {a}")
else:
    print("\nMATCH!")

