def predict_rectangle_fill(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Get all unique row pairs with matching columns
    for r1 in range(h):
        for r2 in range(r1+1, h):
            common_cols = [c for c in range(w) if grid[r1][c] == 2 and grid[r2][c] == 2]
            if len(common_cols) < 2:
                continue

            # Sort common columns
            common_cols.sort()

            # Fill between consecutive column pairs
            for i in range(len(common_cols)-1):
                c1 = common_cols[i]
                c2 = common_cols[i+1]

                # Fill interior rows (between r1 and r2) and interior cols (between c1 and c2)
                for rr in range(r1+1, r2):
                    for cc in range(c1+1, c2):
                        if grid[rr][cc] == 0:
                            result[rr][cc] = 1

    return result

