# Key observation: Look at the intersection points!
# A cell (r,c) fills if there's a vertical alignment AT column c OR horizontal alignment AT row r
# But that doesn't work because (0,4) is in row 0 which has horizontal alignment but shouldn't fill

# Let's think about RECTANGLES formed by 2s:
# If row r1 and row r2 both have 2s at column c, AND row r1 and row r2 both have 2s at column c2,
# then we have a rectangle with corners at (r1,c), (r1,c2), (r2,c), (r2,c2)
# Fill the INTERIOR of such rectangles

def find_rectangles(grid):
    h, w = len(grid), len(grid[0])
    rects = []

    for r1 in range(h):
        for r2 in range(r1+1, h):
            # Get common columns where both rows have 2s
            common_cols = [c for c in range(w) if grid[r1][c] == 2 and grid[r2][c] == 2]
            if len(common_cols) >= 2:
                # This forms a rectangle
                for i in range(len(common_cols)-1):
                    c1, c2 = common_cols[i], common_cols[i+1]
                    rects.append(((r1,c1), (r2,c2)))
    return rects

