    """Fill if cell has EXACTLY ONE 2 in EACH of two opposite directions"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue

            # Count 2s in each direction
            left_2s = [cc for cc in range(c-1, -1, -1) if grid[r][cc] == 2]
            right_2s = [cc for cc in range(c+1, w) if grid[r][cc] == 2]
            above_2s = [(rr, c) for rr in range(r-1, -1, -1) if grid[rr][c] == 2]
            below_2s = [(rr, c) for rr in range(r+1, h) if grid[rr][c] == 2]

            # Fill if exactly one 2 on BOTH sides horizontally OR vertically
            if len(left_2s) == 1 and len(right_2s) == 1:
                result[r][c] = 1
            elif len(above_2s) == 1 and len(below_2s) == 1:
                result[r][c] = 1

    return result

