def solve_arc(grid):
    """Rectangle interior fill with boundary shifting"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Track which rectangles we've processed
    seen_rectangles = set()

    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            twos_r1 = sorted([c for c in range(w) if grid[r1][c] == 2])
            twos_r2 = sorted([c for c in range(w) if grid[r2][c] == 2])

            shared = sorted(set(twos_r1) & set(twos_r2))

            for j in range(len(shared) - 1):
                c1, c2 = shared[j], shared[j+1]

                # Create rectangle ID
                rect_id = (r1, r2, c1, c2)
                if rect_id in seen_rectangles:
                    continue
                seen_rectangles.add(rect_id)

                # Determine interior fill range
                # Find existing 2s in interior rows that act as barriers
                for ri in range(r1 + 1, r2):
                    for ci in range(c1 + 1, c2):
                        # Fill only if cell is 0 and not blocked by an existing 2
                        if grid[ri][ci] == 0:
                            result[ri][ci] = 1

    return result

