                c1, c2 = shared[j], shared[j+1]

                # Is our cell inside this rectangle's interior?
                if r1 < cell_r < r2 and c1 < cell_c < c2:
                    # Check barriers
                    left_barrier = grid[cell_r][c1 + 1] == 2
                    right_barrier = grid[cell_r][c2 - 1] == 2

