# Function to find rectangles between two rows
def find_rectangles_between_rows(r1, r2, grid):
    """Find rectangle formed by rows r1 and r2 sharing columns"""
    rows_cols = {}
    for c in range(grid.shape[1]):
        if grid[r1, c] == 2:
            rows_cols[c] = 'r1'
        elif grid[r2, c] == 2:
            rows_cols[c] = 'r2'

    # Find columns where both rows have 2s
    shared_cols = sorted([c for c, v in rows_cols.items() if v == 'both'])
    if len(shared_cols) < 2:
        return []

    rectangles = []
    for i in range(len(shared_cols)):
        for j in range(i+1, len(shared_cols)):
            c1, c2 = shared_cols[i], shared_cols[j]
            interior_cells = [(r, c) for r in range(r1+1, r2) for c in range(c1+1, c2)]
            if interior_cells:
                rectangles.append((c1, c2, interior_cells))

    return rectangles

